function useLocalState(key, fallback) { const [value, setValue] = useState(() => readState(key, fallback)); useEffect(() => writeState(key, value), [key, value]); return [value, setValue] }
function useReveal() { useEffect(() => { const nodes = document.querySelectorAll('.reveal'); if (!('IntersectionObserver' in window)) { nodes.forEach(node => node.classList.add('is-visible')); return undefined }; const observer = new IntersectionObserver(entries => entries.forEach(entry => { if (entry.isIntersecting) { entry.target.classList.add('is-visible'); observer.unobserve(entry.target) } }), { threshold: .08 }); nodes.forEach(node => observer.observe(node)); return () => observer.disconnect() }, []) }
function getShanghaiKey() { const parts = new Intl.DateTimeFormat('en-US', { timeZone: 'Asia/Shanghai', year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(new Date()); const values = Object.fromEntries(parts.map(part => [part.type, part.value])); return `${values.year}-${values.month}-${values.day}` }
function autoStageId() { const key = getShanghaiKey(); if (key === '2026-07-28') return 'day1'; if (key === '2026-07-29') return 'day2'; if (key === '2026-07-30') return 'day3'; if (key === '2026-07-31') return 'day4'; if (key >= '2026-08-01') return 'memory'; return 'pre' }
function SectionHeading({ eyebrow, title, copy, action }) { return <div className="section-heading"><div><p className="eyebrow">{eyebrow}</p><h2>{title}</h2>{copy && <p className="section-copy">{copy}</p>}</div>{action}</div> }
function Avatar({ person, size = 'small' }) { const key = person === 'Jenny' || person === 'jenny' ? 'jenny' : person === 'Richard' || person === 'richard' ? 'richard' : 'both'; const label = key === 'jenny' ? 'Jenny' : key === 'richard' ? 'Richard' : 'Jenny and Richard'; return <img className={`avatar avatar-${size} avatar-${key}`} src={stickers[key]} alt={label} /> }
function MatchSticker({ compact = false }) { return <span className={`match-sticker ${compact ? 'compact' : ''}`}><Avatar person="Both" size={compact ? 'tiny' : 'small'} /><b>Match</b></span> }
function PersonChoice({ person, checked, onClick }) { return <button type="button" className={`person-choice ${person} ${checked ? 'checked' : ''}`} onClick={onClick}><span className="person-choice-main"><Avatar person={person} size="tiny" /><b>{person === 'jenny' ? 'Jenny' : 'Richard'}</b></span><span>{checked ? '已选 ✓' : '选择'}</span></button> }
function StageSwitcher({ selectedId, autoId, setSelectedId }) { return <div className="mode-switcher">{[...days, { ...memoryData }].map(day => <button type="button" key={day.id} className={`${selectedId === day.id ? 'active' : ''} ${day.id === autoId ? 'auto' : ''}`} onClick={() => setSelectedId(day.id)}><b>{day.label}</b><small>{day.date}</small></button>)}</div> }

function TodayMode({ stage, autoId, selectedId, setSelectedId, checklist, toggleChecklist, ready, toggleReady }) {
  const safeStage = dayMap[stage?.id] || dayMap.pre
  const safeChecklist = Array.isArray(safeStage.checklist) ? safeStage.checklist : []
  const safePending = Array.isArray(safeStage.pending) ? safeStage.pending : []
  const readyState = ready?.[safeStage.id] || {}
  return <section className="today-section content-section" id="today"><SectionHeading eyebrow="01 / Today mode" title="今天要做什么" copy="按北京时间自动显示，也可以提前看明天。" action={<div className="today-heading-actions"><span className="time-badge">Asia / Shanghai</span><span className="weather-note">天气：出发前查看</span></div>} /><StageSwitcher selectedId={selectedId} autoId={autoId} setSelectedId={setSelectedId} /><div className="today-card reveal"><div className="today-head"><div><span className="today-date">{safeStage.date} · {safeStage.ticket}</span><h3>{safeStage.title}</h3><p>{safeStage.mood}</p></div><span className="auto-mark">{selectedId === autoId ? 'TODAY' : 'PREVIEW'}</span></div><div className="next-action"><span>下一件事</span><strong>{safeStage.next}</strong></div><div className="today-columns"><div><span className="field-label">今天最要紧</span><div className="today-checks">{safeChecklist.slice(0, 5).map(item => { const key = `${safeStage.id}-${item}`; return <button type="button" className={checklist?.[key] ? 'checked' : ''} key={item} onClick={() => toggleChecklist(key)}><i>{checklist?.[key] ? '✓' : ''}</i>{item}</button> })}</div></div><div><span className="field-label">今日待确认</span><ul className="pending-list">{safePending.map(item => <li key={item}>{item}</li>)}</ul></div></div><div className="today-task"><span>今日照片任务</span><p>{safeStage.task || '今天先好好在一起。'}</p></div><details className="practical-info"><summary>酒店与天气信息</summary><p>安吉中南度假 · 东非草原酒店</p><p>上海 → 安吉，自驾约 3–3.5 小时</p><a href="https://uri.amap.com/search?keyword=%E5%AE%89%E5%90%89%E4%B8%AD%E5%8D%97%E5%BA%A6%E5%81%87%20%E4%B8%9C%E9%9D%9E%E8%8D%89%E5%8E%9F%E9%85%92%E5%BA%97" target="_blank" rel="noreferrer">打开高德搜索 ↗</a></details><div className="ready-row"><span className="field-label">出发前，两个人都点一下</span><div><PersonChoice person="jenny" checked={readyState.jenny} onClick={() => toggleReady(safeStage.id, 'jenny')} /><PersonChoice person="richard" checked={readyState.richard} onClick={() => toggleReady(safeStage.id, 'richard')} /></div>{readyState.jenny && readyState.richard && <strong className="all-set">All set. 出发。</strong>}</div></div></section>
}

function MemoryMode({ selectedId, setSelectedId, photos, memories, decisions, completedTasks, seal, setSeal }) {
  const safePhotos = Array.isArray(photos) ? photos : []
  const safeMemories = memories && typeof memories === 'object' ? memories : {}
  const matches = Object.values(decisions || {}).filter(item => item?.jenny && item?.richard).length
  const doneTasks = Object.values(completedTasks || {}).filter(Boolean).length
  const tripCover = safePhotos.find(photo => photo?.isTripCover)
  return <section className="memory-mode-section content-section" id="today"><SectionHeading eyebrow="01 / Memory mode" title={memoryData.title} copy={memoryData.mood} action={<span className="time-badge">after 08/01</span>} /><StageSwitcher selectedId={selectedId} autoId="memory" setSelectedId={setSelectedId} /><div className="memory-empty-note">{safePhotos.length || Object.keys(safeMemories).length ? '这一趟已经留下了一些证据。' : '这里还空着。旅行结束后，它会慢慢长成一本小纪念册。'}</div><div className="trip-cover reveal">{tripCover ? <img src={tripCover.src} alt={tripCover.caption || '旅行封面'} /> : <div className="cover-placeholder"><span>TRIP COVER</span><b>等一张这趟旅行的封面照</b><small>在 Photo Vault 里设为整趟封面</small></div>}<div className="cover-copy"><span>ANJI / MEMORY BOOK</span><h3>山里有风，也有我们</h3><p>Into the Green, With You</p></div></div><div className="memory-highlights"><div><b>{safePhotos.length}</b><span>photos kept</span></div><div><b>{matches}</b><span>matches</span></div><div><b>{doneTasks}</b><span>tiny tasks</span></div></div><div className="memory-glance-grid">{days.filter(day => day.id.startsWith('day')).map(day => { const dayPhotos = safePhotos.filter(photo => photo.day === day.id).slice(0, 4); const note = safeMemories[day.id] || {}; return <article className="memory-glance-card" key={day.id}><div className="glance-photos">{dayPhotos.length ? dayPhotos.map(photo => <img key={photo.id} src={photo.src} alt={photo.caption || day.short} />) : <div className="glance-placeholder">等一张{day.short}的照片</div>}</div><div className="glance-copy"><span>{day.label} · {day.date}</span><strong>{day.title}</strong><p>{note.jenny || note.richard || '这一页还空着，等你们各留一句。'}</p></div></article> })}</div><SealThisTrip seal={seal} setSeal={setSeal} /></section>
}

function PlanSection({ activeDay, setActiveDay, completed, togglePlan }) { const day = dayMap[activeDay] || dayMap.day1; return <section className="plan-section content-section" id="plan"><SectionHeading eyebrow="02 / Four-day plan" title="四天慢慢走" copy="票根比行程表轻一点，展开之后才是细节。" /><div className="ticket-row">{days.filter(item => item.id.startsWith('day')).map(item => <button type="button" className={`plan-ticket ${activeDay === item.id ? 'active' : ''}`} key={item.id} onClick={() => setActiveDay(item.id)}><span>{item.label} · {item.date}</span><strong>{item.short}</strong><i>{activeDay === item.id ? '−' : '+'}</i></button>)}</div><div className={`plan-expanded plan-${day.id}`}><div className="expanded-heading"><span>{day.date} / {day.mood}</span><b>{day.title}</b></div><div className="expanded-plans">{(day.plans || []).map((plan, index) => { const key = `${day.id}-${index}`; return <button type="button" className={`expanded-plan ${completed?.[key] ? 'done' : ''}`} key={key} onClick={() => togglePlan(key)}><span>{plan[0]}</span><i>{completed?.[key] ? '✓' : ''}</i><div><b>{plan[1]}</b><small>{plan[2]}</small></div></button> })}</div><div className="mini-notes"><div><span>COUPLE TASK</span><p>{day.task}</p></div><div><span>PHOTO MISSION</span><p>{day.id === 'day1' ? '酒店第一张合照' : day.id === 'day2' ? '漂流后狼狈照' : day.id === 'day3' ? '不用露脸但很像对方' : '这趟旅行的封面照'}</p></div></div></div></section> }

function DecisionBoard({ places, currentUser, onVote, onAdd, onUpdate, onDelete, cloudMode }) {
  const [activeGroup, setActiveGroup] = useState('play'); const [formOpen, setFormOpen] = useState(false); const [form, setForm] = useState({ title: '', type: 'play', description: '', dayHint: '', mapUrl: '' }); const [editingId, setEditingId] = useState('')
  const group = decisionGroups.find(item => item.id === activeGroup) || decisionGroups[0]
  const groupPlaces = places.filter(place => (place.type || 'other') === activeGroup)
  const save = event => { event.preventDefault(); if (!form.title.trim()) return; const payload = { ...form, title: form.title.trim(), type: form.type, added_by: currentUser, addedBy: currentUser }; if (editingId) onUpdate(editingId, payload); else onAdd(payload); setForm({ title: '', type: activeGroup, description: '', dayHint: '', mapUrl: '' }); setEditingId(''); setFormOpen(false) }
  const status = place => { const votes = place.votes || {}; if (votes.Jenny === 'want' && votes.Richard === 'want') return 'match'; if (votes.Jenny === 'want') return 'jenny'; if (votes.Richard === 'want') return 'richard'; return 'open' }
  return <section className="decision-section content-section" id="decisions"><SectionHeading eyebrow="03 / Decision board" title="一起决定，不用猜" copy="两个人各自点自己的大选项。两边都选，就是 Match。" action={<button className="sticker-add" type="button" onClick={() => { setFormOpen(true); setForm({ ...form, type: activeGroup }) }}>＋ 想到一个地方</button>} /><div className="decision-tabs">{decisionGroups.map(item => <button type="button" className={activeGroup === item.id ? 'active' : ''} key={item.id} onClick={() => setActiveGroup(item.id)}>{item.title}<small>{groupPlaces.length && activeGroup === item.id ? groupPlaces.length : item.items.length}</small></button>)}</div><div className="person-legend"><span className="legend-jenny">♥ Jenny</span><span className="legend-richard">✦ Richard</span><span className="legend-match">● Match</span>{cloudMode ? <span className="sync-mini">共享中</span> : <span className="sync-mini">本地演示</span>}</div>{formOpen && <form className="place-form reveal is-visible" onSubmit={save}><input autoFocus value={form.title} onChange={event => setForm({ ...form, title: event.target.value })} placeholder="地方 / 餐厅 / 临时想去的店" /><select value={form.type} onChange={event => setForm({ ...form, type: event.target.value })}>{decisionGroups.map(item => <option key={item.id} value={item.id}>{item.title}</option>)}</select><input value={form.dayHint} onChange={event => setForm({ ...form, dayHint: event.target.value })} placeholder="适合哪一天，例如 7/29" /><input value={form.mapUrl} onChange={event => setForm({ ...form, mapUrl: event.target.value })} placeholder="地图链接（可选）" /><textarea value={form.description} onChange={event => setForm({ ...form, description: event.target.value })} placeholder="一句备注" rows="2" /><div><button className="primary-button" type="submit">{editingId ? '保存修改' : '加入候选'}</button><button className="ghost-button" type="button" onClick={() => setFormOpen(false)}>先不加</button></div></form>}<div className="decision-group reveal"><div className="group-heading"><span>{activeGroup === 'play' ? '01' : activeGroup === 'eat' ? '02' : '03'}</span><h3>{group.title}</h3></div><div className="decision-grid">{(groupPlaces.length ? groupPlaces : group.items.map(([title, icon]) => ({ id: `${activeGroup}-${title}`, title, type: activeGroup, icon, votes: {} }))).map(place => { const state = status(place); const votes = place.votes || {}; return <div className={`decision-item ${state}`} key={place.id}><div className="decision-main"><span className="decision-icon">{place.icon || '✦'}</span><strong>{place.title}</strong><em>{state === 'match' ? 'Match' : state === 'jenny' ? 'Jenny chose' : state === 'richard' ? 'Richard chose' : 'Open'}</em>{place.description && <small>{place.description}</small>}</div><div className="decision-people"><PersonChoice person="jenny" checked={votes.Jenny === 'want'} onClick={() => onVote(place, 'Jenny')} /><PersonChoice person="richard" checked={votes.Richard === 'want'} onClick={() => onVote(place, 'Richard')} /></div>{place.isRemote && <div className="place-actions">{place.mapUrl && <a href={place.mapUrl} target="_blank" rel="noreferrer">地图 ↗</a>}<button type="button" onClick={() => { setEditingId(place.id); setForm({ title: place.title, type: place.type, description: place.description || '', dayHint: place.dayHint || '', mapUrl: place.mapUrl || '' }); setFormOpen(true) }}>编辑</button><button type="button" onClick={() => onDelete(place)}>删除</button></div>}</div> })}</div></div></section>
}

function ChecklistSection({ items, currentUser, onToggle, onAdd, onUpdate, onDelete, cloudMode }) { const [activePack, setActivePack] = useState('basics'); const [filter, setFilter] = useState('all'); const [hideCompleted, setHideCompleted] = useState(false); const [label, setLabel] = useState(''); const group = packGroups.find(item => item.id === activePack) || packGroups[0]; const visible = items.filter(item => item.category === activePack && (!hideCompleted || !item.checked) && (filter === 'all' || filter === 'unfinished' && !item.checked || filter === item.owner || filter === 'mine' && (item.owner === currentUser || item.owner === 'Both'))); const done = items.filter(item => item.category === activePack && item.checked).length; const add = event => { event.preventDefault(); if (!label.trim()) return; onAdd({ title: label.trim(), category: activePack, owner: 'Both', created_by: currentUser, updated_by: currentUser }); setLabel('') }; return <section className="packing-section content-section" id="packing"><SectionHeading eyebrow="04 / Master packing list" title="打包清单" copy="完整清单在这里，Today 只提醒今天最要紧的。" /><div className="pack-summary"><strong>{done} / {items.filter(item => item.category === activePack).length}</strong><span>已完成 · {group.label}</span><div className="pack-progress"><i style={{ width: `${items.filter(item => item.category === activePack).length ? (done / items.filter(item => item.category === activePack).length) * 100 : 0}%` }} /></div></div><div className="pack-tabs">{packGroups.map(item => <button type="button" className={activePack === item.id ? 'active' : ''} key={item.id} onClick={() => setActivePack(item.id)}>{item.label}<small>{items.filter(row => row.category === item.id).length}</small></button>)}</div><div className="pack-tools"><button type="button" className={hideCompleted ? 'active' : ''} onClick={() => setHideCompleted(value => !value)}>{hideCompleted ? '显示已完成' : '隐藏已完成'}</button>{['all', 'Jenny', 'Richard', 'unfinished'].map(item => <button type="button" className={filter === item ? 'active' : ''} key={item} onClick={() => setFilter(item)}>{item === 'all' ? '全部' : item === 'unfinished' ? '未完成' : `只看 ${item}`}</button>)}</div><div className="pack-card"><div className="pack-card-head"><span>{group.label}</span><b>{done} / {items.filter(item => item.category === activePack).length}</b></div><div className="pack-grid">{visible.length ? visible.map(item => <div className={`pack-item ${item.checked ? 'checked' : ''}`} key={item.id}><button type="button" className="pack-check" onClick={() => onToggle(item)}><i>{item.checked ? '✓' : ''}</i><span>{item.label}</span></button><div className="pack-assignee"><button type="button" className={item.owner === 'Jenny' ? 'active jenny' : ''} onClick={() => onUpdate(item.id, { owner: item.owner === 'Jenny' ? 'Both' : 'Jenny', updated_by: currentUser })}>Jenny</button><button type="button" className={item.owner === 'Richard' ? 'active richard' : ''} onClick={() => onUpdate(item.id, { owner: item.owner === 'Richard' ? 'Both' : 'Richard', updated_by: currentUser })}>Richard</button><button type="button" className="item-edit" onClick={() => { const next = window.prompt('改一下这项的名字', item.label); if (next?.trim()) onUpdate(item.id, { title: next.trim(), label: next.trim(), updated_by: currentUser }) }}>编辑</button><button type="button" className="item-delete" onClick={() => { if (window.confirm('删掉这项？对方也会看不到。')) onDelete(item) }}>×</button></div></div>) : <div className="pack-empty">这一类还没有未完成事项，或者已经整理好了。</div>}</div><form className="pack-add" onSubmit={add}><input value={label} onChange={event => setLabel(event.target.value)} placeholder={`给「${group.label}」新增一项`} /><button type="submit">＋ 添加</button></form></div><p className="sync-note">{cloudMode ? '这份清单会在 Jenny 和 Richard 的手机之间同步。' : '本地演示模式：配置 Supabase 后两台手机会共享这份清单。'}</p></section> }

function CoupleMode({ taskIndex, setTaskIndex, questionIndex, setQuestionIndex, taskDone, setTaskDone, couple, setCouple }) { const choose = (person, value) => setCouple(current => ({ ...current, tonight: { ...(current.tonight || {}), [person]: current.tonight?.[person] === value ? '' : value } })); return <section className="couple-section content-section" id="couple"><SectionHeading eyebrow="05 / Couple mode" title="给两个人的小按钮" copy="不测什么，只留一点今天的默契。" /><div className="couple-grid"><div className="couple-task-card"><span className="eyebrow">Today’s tiny task</span><h3>{dailyTasks[taskIndex]}</h3><div className="couple-task-actions"><button type="button" onClick={() => setTaskIndex((taskIndex + 1) % dailyTasks.length)}>更新小任务 ↻</button><button type="button" className={taskDone[taskIndex] ? 'done' : ''} onClick={() => setTaskDone(current => ({ ...current, [taskIndex]: !current[taskIndex] }))}>{taskDone[taskIndex] ? '已完成 ✓' : '完成这件小事'}</button></div></div><div className="question-card"><span className="eyebrow">Question card / {questionIndex + 1}</span><p>{questions[questionIndex]}</p><button type="button" onClick={() => setQuestionIndex((questionIndex + 1) % questions.length)}>换一个问题 →</button></div><div className="two-choice-card"><span className="eyebrow">Tonight / 二选一</span><h3>晚上想要什么节奏？</h3><div className="large-choice-grid">{[['散步', '把话说慢一点'], ['微醺', '回房间再聊一会儿']].map(([value, copy]) => <div className="large-choice" key={value}><strong>{value}</strong><small>{copy}</small><PersonChoice person="jenny" checked={couple.tonight?.jenny === value} onClick={() => choose('jenny', value)} /><PersonChoice person="richard" checked={couple.tonight?.richard === value} onClick={() => choose('richard', value)} /></div>)}</div></div></div></section> }

function PhotoVault({ photos, currentUser, cloudMode, onUpload, onUpdate, onDelete }) { const [activeDay, setActiveDay] = useState('day1'); const [photoType, setPhotoType] = useState('Us'); const dayPhotos = photos.filter(photo => photo.day === activeDay); const upload = event => { const file = event.target.files?.[0]; if (file) onUpload(file, { day: activeDay, type: photoType, uploadedBy: currentUser }); event.target.value = '' }; return <section className="vault-section content-section" id="vault"><SectionHeading eyebrow="06 / Photo vault" title="照片小抽屉" copy={cloudMode ? '照片会同步到两个人的设备。' : '本地演示模式：配置 Supabase 后照片会同步。'} /><div className="vault-top"><div className="vault-tabs">{days.filter(day => day.id.startsWith('day')).map(day => <button type="button" className={activeDay === day.id ? 'active' : ''} key={day.id} onClick={() => setActiveDay(day.id)}>{day.label}<small>{day.date}</small></button>)}</div><div className="vault-controls"><span>照片类型</span>{photoTypes.map(type => <button type="button" className={photoType === type ? 'active' : ''} key={type} onClick={() => setPhotoType(type)}>{type}</button>)}</div></div><label className="upload-sticker">＋ 添加今天的一张照片<input type="file" accept="image/*" onChange={upload} /></label>{dayPhotos.length === 0 ? <div className="vault-empty"><span>✹</span><b>这里还空着，等一张今天的我们。</b><small>点上面的贴纸，把照片放进 Day {activeDay.slice(-1)}。</small></div> : <div className="photo-grid">{dayPhotos.map(photo => <article className="photo-card" key={photo.id}><div className="photo-frame"><img src={photo.src} alt={photo.caption || `${activeDay} photo`} />{photo.isDayCover && <span className="cover-stamp">DAY COVER</span>}{photo.isTripCover && <span className="trip-stamp">TRIP COVER</span>}</div><div className="photo-card-body"><div className="photo-meta"><span>{photo.uploadedBy} · {photo.type}</span><button type="button" onClick={() => onUpdate(photo.id, { isDayCover: true })}>{photo.isDayCover ? '已是当天封面' : '设为当天封面'}</button><button type="button" onClick={() => onUpdate(photo.id, { isTripCover: true })}>{photo.isTripCover ? '整趟封面 ✓' : '设为整趟封面'}</button><button type="button" className="item-delete" onClick={() => { if (window.confirm('确定删除这张照片吗？Richard 那边也会同步消失。')) onDelete(photo) }}>删除</button></div><textarea value={photo.caption || ''} onChange={event => onUpdate(photo.id, { caption: event.target.value })} placeholder="给这张照片留一句 caption" rows="2" /></div></article>)}</div>}</section> }

function MemorySection({ memories, setMemories }) { const safe = memories && typeof memories === 'object' ? memories : {}; const update = (day, key, value) => setMemories(current => ({ ...(current || {}), [day]: { ...(current?.[day] || {}), [key]: value } })); return <section className="memory-section" id="memory"><div className="memory-inner"><SectionHeading eyebrow="07 / Memory log" title="每天留下三句话" copy="Jenny 和 Richard 都可以写，不用写得完美。" /><label className="memory-note-label">旅行备注<textarea value={safe.note || ''} onChange={event => setMemories(current => ({ ...(current || {}), note: event.target.value }))} placeholder="把还没决定的事、想补的链接，或者一句突然想到的话放在这里。" rows="2" /></label><div className="memory-grid">{days.filter(day => day.id.startsWith('day')).map(day => <article className="memory-card reveal" key={day.id}><div className="memory-card-head"><span>{day.label} · {day.date}</span><i>{day.mood}</i></div><strong>{day.title}</strong>{[['jenny', 'Jenny 的一句话', '今天最喜欢的瞬间'], ['richard', 'Richard 的一句话', '今天想记住什么'], ['funny', '最好笑的一刻', '不用完整'], ['comfortable', '最舒服的一刻', '留给以后']].map(([key, label, placeholder]) => <label key={key}>{label}<textarea value={safe[day.id]?.[key] || ''} onChange={event => update(day.id, key, event.target.value)} placeholder={placeholder} rows="2" /></label>)}</article>)}</div></div></section> }
function SealThisTrip({ seal, setSeal }) { const safe = seal || {}; const update = (key, value) => setSeal(current => ({ ...(current || {}), [key]: value })); return <div className="seal-trip"><div className="seal-trip-head"><span>✹</span><div><b>Seal This Trip</b><small>ANJI / 2026 · MADE FOR TWO</small></div></div>{[['title', '这趟旅行的名字', '比如：山里有风，也有我们'], ['favoritePhoto', '最喜欢的一张照片', '写 Day / 照片 caption'], ['funny', '最好笑的一刻', '以后看到还会笑的那一刻'], ['comfortable', '最舒服的一刻', '风、泳池、咖啡，或者某个普通瞬间'], ['next', '下次还想一起做什么', '留给下一次'], ['note', '一句话写给这几天的我们', '写给这趟旅行']].map(([key, label, placeholder], index) => <label key={key}>{label}{index < 2 ? <input value={safe[key] || ''} onChange={event => update(key, event.target.value)} placeholder={placeholder} /> : <textarea value={safe[key] || ''} onChange={event => update(key, event.target.value)} placeholder={placeholder} rows="2" />}</label>)}<div className="seal-line">not ready to seal yet · keep adding</div></div> }
function IdentityModal({ onSelect }) { return <div className="identity-backdrop"><div className="identity-modal"><span className="eyebrow">A shared trip for two</span><h2>今天是谁在用？</h2><p>选择后，投票、上传和新增内容都会记下是谁做的。</p><div><button type="button" className="identity-jenny" onClick={() => onSelect('Jenny')}>♥ Jenny</button><button type="button" className="identity-richard" onClick={() => onSelect('Richard')}>✦ Richard</button></div></div></div> }
function SyncBanner({ status }) { if (!status.error && !status.loading && status.cloud) return null; return <div className={`sync-banner ${status.error ? 'error' : ''}`}>{status.error ? '同步失败，稍后再试。' : status.loading ? '正在同步两个人的旅行记录…' : '本地演示模式 · 配置 Supabase 后即可共享'}</div> }
function BottomNav() { return <nav className="bottom-nav"><a href="#today"><span>☼</span>Today</a><a href="#plan"><span>▤</span>Plan</a><a href="#decisions"><span>✦</span>Decide</a><a href="#memory"><span>♡</span>Memory</a></nav> }

function DecisionBoardRefined({ places, currentUser, onVote, onAdd, onUpdate, onDelete, cloudMode }) {
  const [activeGroup, setActiveGroup] = useState('play')
  const [formOpen, setFormOpen] = useState(false)
  const [editingId, setEditingId] = useState('')
  const [form, setForm] = useState({ title: '', type: 'play', description: '', dayHint: '', mapUrl: '' })
  const group = decisionGroups.find(item => item.id === activeGroup) || decisionGroups[0]
  const groupPlaces = places.filter(place => (place.type || 'other') === activeGroup)
  const status = place => { const votes = place.votes || {}; if (votes.Jenny === 'want' && votes.Richard === 'want') return 'match'; if (votes.Jenny === 'want') return 'jenny'; if (votes.Richard === 'want') return 'richard'; return 'open' }
  const save = event => { event.preventDefault(); if (!form.title.trim()) return; const payload = { ...form, title: form.title.trim(), added_by: currentUser, addedBy: currentUser }; if (editingId) onUpdate(editingId, payload); else onAdd(payload); setEditingId(''); setForm({ title: '', type: activeGroup, description: '', dayHint: '', mapUrl: '' }); setFormOpen(false) }
  return <section className="decision-section content-section" id="decisions"><SectionHeading eyebrow="03 / Decision board" title="一起决定，不用猜" copy="每个人点自己的选择。两边都选，就盖一枚 Match 章。" action={<button className="sticker-add" type="button" onClick={() => { setFormOpen(true); setForm(current => ({ ...current, type: activeGroup })) }}>＋ 想到一个地方</button>} /><div className="decision-tabs">{decisionGroups.map(item => <button type="button" className={activeGroup === item.id ? 'active' : ''} key={item.id} onClick={() => setActiveGroup(item.id)}>{item.title}<small>{groupPlaces.length && activeGroup === item.id ? groupPlaces.length : item.items.length}</small></button>)}</div><div className="person-legend"><span className="legend-jenny">♥ Jenny</span><span className="legend-richard">✦ Richard</span><span className="legend-match">● Match</span>{cloudMode ? <span className="sync-mini">共享中</span> : <span className="sync-mini">本地演示</span>}</div>{formOpen && <form className="place-form reveal is-visible" onSubmit={save}><input autoFocus value={form.title} onChange={event => setForm({ ...form, title: event.target.value })} placeholder="地方 / 餐厅 / 临时想去的店" /><select value={form.type} onChange={event => setForm({ ...form, type: event.target.value })}>{decisionGroups.map(item => <option key={item.id} value={item.id}>{item.title}</option>)}</select><input value={form.dayHint} onChange={event => setForm({ ...form, dayHint: event.target.value })} placeholder="适合哪一天，例如 7/29" /><input value={form.mapUrl} onChange={event => setForm({ ...form, mapUrl: event.target.value })} placeholder="地图链接（可选）" /><textarea value={form.description} onChange={event => setForm({ ...form, description: event.target.value })} placeholder="一句备注" rows="2" /><div><button className="primary-button" type="submit">{editingId ? '保存修改' : '加入候选'}</button><button className="ghost-button" type="button" onClick={() => setFormOpen(false)}>先不加</button></div></form>}<div className="decision-group reveal"><div className="group-heading"><span>{activeGroup === 'play' ? '01' : activeGroup === 'eat' ? '02' : '03'}</span><h3>{group.title}</h3></div><div className="decision-grid">{(groupPlaces.length ? groupPlaces : group.items.map(([title, icon]) => ({ id: `${activeGroup}-${title}`, title, type: activeGroup, icon, votes: {} }))).map(place => { const state = status(place); const votes = place.votes || {}; return <div className={`decision-item ${state}`} key={place.id}><div className="decision-main"><span className="decision-icon">{place.icon || '✦'}</span><strong>{place.title}</strong><em>{state === 'match' ? 'Match' : state === 'jenny' ? 'Jenny chose' : state === 'richard' ? 'Richard chose' : 'Open'}</em>{state === 'match' && <MatchSticker compact />}{place.description && <small>{place.description}</small>}</div><div className="decision-people"><PersonChoice person="jenny" checked={votes.Jenny === 'want'} onClick={() => onVote(place, 'Jenny')} /><PersonChoice person="richard" checked={votes.Richard === 'want'} onClick={() => onVote(place, 'Richard')} /></div>{place.isRemote && <div className="place-actions">{place.mapUrl && <a href={place.mapUrl} target="_blank" rel="noreferrer">地图 ↗</a>}<button type="button" onClick={() => { setEditingId(place.id); setForm({ title: place.title, type: place.type, description: place.description || '', dayHint: place.dayHint || '', mapUrl: place.mapUrl || '' }); setFormOpen(true) }}>编辑</button><button type="button" onClick={() => onDelete(place)}>删除</button></div>}</div> })}</div></div></section>
}

function ChecklistSectionRefined({ items, currentUser, onToggle, onAdd, onUpdate, onDelete, cloudMode }) {
  const [activePack, setActivePack] = useState('basics'); const [filter, setFilter] = useState('all'); const [hideCompleted, setHideCompleted] = useState(false); const [label, setLabel] = useState('')
  const group = packGroups.find(item => item.id === activePack) || packGroups[0]; const categoryItems = items.filter(item => item.category === activePack); const visible = categoryItems.filter(item => (!hideCompleted || !item.checked) && (filter === 'all' || filter === 'unfinished' && !item.checked || filter === item.owner || filter === 'mine' && (item.owner === currentUser || item.owner === 'Both'))); const done = categoryItems.filter(item => item.checked).length
  const add = event => { event.preventDefault(); if (!label.trim()) return; onAdd({ title: label.trim(), category: activePack, owner: 'Both', created_by: currentUser, updated_by: currentUser }); setLabel('') }
  const owner = (item, value) => onUpdate(item.id, { owner: value, updated_by: currentUser })
  return <section className="packing-section content-section" id="packing"><SectionHeading eyebrow="04 / Master packing list" title="打包清单" copy="完整清单在这里，Today 只提醒今天最要紧的。" /><div className="pack-summary"><strong>{done} / {categoryItems.length}</strong><span>已完成 · {group.label}</span><div className="pack-progress"><i style={{ width: `${categoryItems.length ? (done / categoryItems.length) * 100 : 0}%` }} /></div></div><div className="pack-tabs">{packGroups.map(item => <button type="button" className={activePack === item.id ? 'active' : ''} key={item.id} onClick={() => setActivePack(item.id)}>{item.label}<small>{items.filter(row => row.category === item.id).length}</small></button>)}</div><div className="pack-tools"><button type="button" className={hideCompleted ? 'active' : ''} onClick={() => setHideCompleted(value => !value)}>{hideCompleted ? '显示已完成' : '隐藏已完成'}</button></div><div className="pack-tools pack-filter-tools">{['all', 'Jenny', 'Richard', 'unfinished', 'mine'].map(item => <button type="button" className={filter === item ? 'active' : ''} key={item} onClick={() => setFilter(item)}>{item === 'all' ? '全部' : item === 'unfinished' ? '未完成' : item === 'mine' ? '只看我负责' : `只看 ${item}`}</button>)}</div><div className="pack-card"><div className="pack-card-head"><span>{group.label}</span><b>{done} / {categoryItems.length}</b></div><div className="pack-grid">{visible.length ? visible.map(item => <div className={`pack-item ${item.checked ? 'checked' : ''}`} key={item.id}><button type="button" className="pack-check" onClick={() => onToggle(item)}><i>{item.checked ? '✓' : ''}</i><span>{item.label}</span></button><div className="pack-assignee"><button type="button" className={item.owner === 'Jenny' ? 'active jenny' : ''} aria-label="Jenny 负责" title="Jenny 负责" onClick={() => owner(item, 'Jenny')}><Avatar person="Jenny" size="tiny" /></button><button type="button" className={item.owner === 'Richard' ? 'active richard' : ''} aria-label="Richard 负责" title="Richard 负责" onClick={() => owner(item, 'Richard')}><Avatar person="Richard" size="tiny" /></button><button type="button" className={item.owner === 'Both' || !item.owner ? 'active both' : ''} aria-label="两个人一起负责" title="两个人一起负责" onClick={() => owner(item, 'Both')}><Avatar person="Both" size="tiny" /></button><button type="button" className="item-edit" onClick={() => { const next = window.prompt('改一下这项的名字', item.label); if (next?.trim()) onUpdate(item.id, { title: next.trim(), label: next.trim(), updated_by: currentUser }) }}>编辑</button><button type="button" className="item-delete" onClick={() => { if (window.confirm('删掉这项？对方也会看不到。')) onDelete(item) }}>删除</button></div></div>) : <div className="pack-empty">这一类还没有未完成事项，或者已经整理好了。</div>}</div><form className="pack-add" onSubmit={add}><input value={label} onChange={event => setLabel(event.target.value)} placeholder={`给「${group.label}」新增一项`} /><button type="submit">＋ 添加</button></form></div><p className="sync-note">{cloudMode ? '这份清单会在 Jenny 和 Richard 的手机之间同步。' : '本地演示模式：配置 Supabase 后两台手机会共享这份清单。'}</p></section>
}

function PhotoVaultRefined({ photos, currentUser, cloudMode, onUpload, onUpdate, onDelete }) {
  const [activeDay, setActiveDay] = useState('day1'); const [photoType, setPhotoType] = useState('Us'); const dayPhotos = photos.filter(photo => photo.day === activeDay); const upload = event => { const file = event.target.files?.[0]; if (file) onUpload(file, { day: activeDay, type: photoType, uploadedBy: currentUser }); event.target.value = '' }
  return <section className="vault-section content-section" id="vault"><SectionHeading eyebrow="06 / Photo vault" title="照片小抽屉" copy={cloudMode ? '照片会同步到两个人的设备。' : '本地演示模式：配置 Supabase 后照片会同步。'} /><div className="vault-top"><div className="vault-tabs">{days.filter(day => day.id.startsWith('day')).map(day => <button type="button" className={activeDay === day.id ? 'active' : ''} key={day.id} onClick={() => setActiveDay(day.id)}>{day.label}<small>{day.date}</small></button>)}</div><div className="vault-controls"><span>照片类型</span>{photoTypes.map(type => <button type="button" className={photoType === type ? 'active' : ''} key={type} onClick={() => setPhotoType(type)}>{type}</button>)}</div></div><label className="upload-sticker">＋ 添加今天的一张照片<input type="file" accept="image/*" onChange={upload} /></label>{dayPhotos.length === 0 ? <div className="vault-empty"><span>✹</span><b>这里还空着，等一张今天的我们。</b><small>点上面的贴纸，把照片放进 Day {activeDay.slice(-1)}。</small></div> : <div className="photo-grid">{dayPhotos.map(photo => <article className="photo-card" key={photo.id}><div className="photo-frame"><img src={photo.src} alt={photo.caption || `${activeDay} photo`} />{photo.isDayCover && <span className="cover-stamp">DAY COVER</span>}{photo.isTripCover && <span className="trip-stamp">TRIP COVER</span>}</div><div className="photo-card-body"><div className="photo-meta"><span><Avatar person={photo.uploadedBy} size="tiny" />{photo.uploadedBy} · {photo.type}</span><button type="button" onClick={() => onUpdate(photo.id, { isDayCover: true })}>{photo.isDayCover ? '已是当天封面' : '设为当天封面'}</button><button type="button" onClick={() => onUpdate(photo.id, { isTripCover: true })}>{photo.isTripCover ? '整趟封面 ✓' : '设为整趟封面'}</button><button type="button" className="item-delete" onClick={() => { if (window.confirm('确定删除这张照片吗？Richard 那边也会同步消失。')) onDelete(photo) }}>删除</button></div><label className="caption-editor"><Avatar person={photo.captionBy || photo.uploadedBy} size="tiny" /><textarea value={photo.caption || ''} onChange={event => onUpdate(photo.id, { caption: event.target.value, captionBy: currentUser })} placeholder="给这张照片留一句 caption" rows="2" /></label></div></article>)}</div>}</section>
}

function MemorySectionRefined({ memories, setMemories }) { const safe = memories && typeof memories === 'object' ? memories : {}; const update = (day, key, value) => setMemories(current => ({ ...(current || {}), [day]: { ...(current?.[day] || {}), [key]: value } })); return <section className="memory-section" id="memory"><div className="memory-inner"><SectionHeading eyebrow="07 / Memory log" title="每天留下三句话" copy="Jenny 和 Richard 都可以写，不用写得完美。" /><label className="memory-note-label">旅行备注<textarea value={safe.note || ''} onChange={event => setMemories(current => ({ ...(current || {}), note: event.target.value }))} placeholder="把还没决定的事、想补的链接，或者一句突然想到的话放在这里。" rows="2" /></label><div className="memory-grid">{days.filter(day => day.id.startsWith('day')).map(day => <article className="memory-card reveal" key={day.id}><div className="memory-card-head"><span>{day.label} · {day.date}</span><i>{day.mood}</i></div><strong>{day.title}</strong><label><Avatar person="Jenny" size="tiny" /><span>Jenny 的一句话</span><textarea value={safe[day.id]?.jenny || ''} onChange={event => update(day.id, 'jenny', event.target.value)} placeholder="今天最喜欢的瞬间" rows="2" /></label><label><Avatar person="Richard" size="tiny" /><span>Richard 的一句话</span><textarea value={safe[day.id]?.richard || ''} onChange={event => update(day.id, 'richard', event.target.value)} placeholder="今天想记住什么" rows="2" /></label><label><span>最好笑的一刻</span><textarea value={safe[day.id]?.funny || ''} onChange={event => update(day.id, 'funny', event.target.value)} placeholder="不用完整" rows="2" /></label><label><span>最舒服的一刻</span><textarea value={safe[day.id]?.comfortable || ''} onChange={event => update(day.id, 'comfortable', event.target.value)} placeholder="留给以后" rows="2" /></label></article>)}</div></div></section> }

/* Keep the existing app wiring, but route it through the refined semantic components. */
DecisionBoard = DecisionBoardRefined
ChecklistSection = ChecklistSectionRefined
PhotoVault = PhotoVaultRefined
MemorySection = MemorySectionRefined

function App() {
  const autoId = autoStageId(); const [selectedView, setSelectedView] = useLocalState('anji-selected-view-v2', autoId); const selectedId = ['pre', 'day1', 'day2', 'day3', 'day4', 'memory'].includes(selectedView) ? selectedView : autoId; const [currentUser, setCurrentUser] = useLocalState('currentUser', ''); const [checklist, setChecklist] = useLocalState('anji-checklist-v3', {}); const [ready, setReady] = useLocalState('anji-ready-v3', {}); const [completed, setCompleted] = useLocalState('anji-plan-v3', {}); const [decisions, setDecisions] = useLocalState('anji-decisions-v3', {}); const [memories, setMemories] = useLocalState('anji-memories-v3', {}); const [couple, setCouple] = useLocalState('anji-couple-v3', {}); const [completedTasks, setCompletedTasks] = useLocalState('anji-tasks-v1', {}); const [seal, setSeal] = useLocalState('anji-seal-v1', {}); const [photos, setPhotos] = useLocalState('anji-photos-cache-v2', []); const [packingItems, setPackingItems] = useLocalState('anji-packing-cache-v2', defaultPacking()); const [places, setPlaces] = useLocalState('anji-places-cache-v2', defaultPlaces()); const [status, setStatus] = useState({ cloud: cloudEnabled, loading: cloudEnabled, error: '' }); const [navOpen, setNavOpen] = useState(false); const [taskIndex, setTaskIndex] = useState(0); const [questionIndex, setQuestionIndex] = useState(0); useReveal()
  const refreshCloud = async () => { if (!cloudEnabled) return; const [nextPhotos, nextPacking, nextPlaces] = await Promise.all([fetchPhotos(), fetchPackingItems(), fetchPlaces()]); setPhotos(nextPhotos); setPackingItems(nextPacking); setPlaces(nextPlaces) }
  useEffect(() => { if (!cloudEnabled) { setStatus({ cloud: false, loading: false, error: '' }); return undefined }; let live = true; const load = async () => { try { let [nextPhotos, nextPacking, nextPlaces] = await Promise.all([fetchPhotos(), fetchPackingItems(), fetchPlaces()]); if (!nextPacking.length) { const rows = defaultPacking().map(item => ({ title: item.label, category: item.category, owner: 'Both', checked: false, created_by: 'Jenny', updated_by: 'Jenny' })); nextPacking = await seedPackingItems(rows) }; if (!nextPlaces.length) { const rows = defaultPlaces().map(item => ({ title: item.title, type: item.type, description: '', day_hint: '', map_url: '', added_by: 'Jenny' })); nextPlaces = await seedPlaces(rows) }; if (live) { setPhotos(nextPhotos); setPackingItems(nextPacking); setPlaces(nextPlaces); setStatus({ cloud: true, loading: false, error: '' }) } } catch (error) { console.error(error); if (live) setStatus({ cloud: true, loading: false, error: 'sync' }) } }; load(); const unsubscribe = subscribeToSharedData(() => refreshCloud().catch(error => { console.error(error); setStatus(current => ({ ...current, error: 'sync', loading: false })) })); return () => { live = false; unsubscribe() } }, [])
  const sync = async action => { if (!cloudEnabled) return action(); setStatus(current => ({ ...current, loading: true, error: '' })); try { const result = await action(); await refreshCloud(); setStatus(current => ({ ...current, loading: false, error: '' })); return result } catch (error) { console.error(error); setStatus(current => ({ ...current, loading: false, error: 'sync' })); return undefined } }
  const toggleChecklist = key => setChecklist(current => ({ ...current, [key]: !current[key] })); const toggleReady = (id, person) => setReady(current => ({ ...current, [id]: { ...(current[id] || {}), [person]: !current[id]?.[person] } })); const togglePlan = key => setCompleted(current => ({ ...current, [key]: !current[key] }));
  const onPackingToggle = item => cloudEnabled && item.custom ? sync(() => updatePackingItem(item.id, { checked: !item.checked, updated_by: currentUser })) : setPackingItems(current => current.map(row => row.id === item.id ? { ...row, checked: !row.checked } : row)); const onPackingAdd = payload => cloudEnabled ? sync(() => createPackingItem(payload)) : setPackingItems(current => [...current, { id: `custom-${Date.now()}`, label: payload.title, category: payload.category, owner: payload.owner, checked: false, createdBy: currentUser, custom: true }]); const onPackingUpdate = (id, patch) => cloudEnabled ? sync(() => updatePackingItem(id, { ...patch, title: patch.title || patch.label, updated_by: currentUser })) : setPackingItems(current => current.map(row => row.id === id ? { ...row, ...patch, label: patch.label || patch.title || row.label } : row)); const onPackingDelete = item => cloudEnabled ? sync(() => deletePackingItem(item.id)) : setPackingItems(current => current.filter(row => row.id !== item.id));
  const onPlaceAdd = payload => cloudEnabled ? sync(() => createPlace(payload)) : setPlaces(current => [...current, { ...payload, id: `custom-place-${Date.now()}`, votes: {}, addedBy: currentUser, isRemote: true }]); const onPlaceUpdate = (id, payload) => cloudEnabled ? sync(() => updatePlace(id, { title: payload.title, type: payload.type, description: payload.description, day_hint: payload.dayHint || '', map_url: payload.mapUrl || '' })) : setPlaces(current => current.map(row => row.id === id ? { ...row, ...payload } : row)); const onPlaceDelete = place => { if (!window.confirm('删掉这个地方？两个人的投票也会一起删除。')) return; cloudEnabled ? sync(() => deletePlace(place.id)) : setPlaces(current => current.filter(row => row.id !== place.id)) }; const onVote = (place, person) => { if (cloudEnabled && place.isRemote) return sync(() => savePlaceVote(place.id, person, place.votes?.[person] === 'want' ? 'skip' : 'want')); setPlaces(current => current.map(row => row.id === place.id ? { ...row, votes: { ...(row.votes || {}), [person]: row.votes?.[person] === 'want' ? 'skip' : 'want' } } : row)) }
  const onPhotoUpload = async (file, meta) => { if (!cloudEnabled) { const reader = new FileReader(); reader.onload = () => setPhotos(current => [{ id: `${Date.now()}-${file.name}`, day: meta.day, src: reader.result, caption: '', type: meta.type, uploadedBy: currentUser, isDayCover: !current.some(photo => photo.day === meta.day), isTripCover: current.length === 0 }, ...current]); reader.readAsDataURL(file); return }; await sync(async () => { const photo = await uploadPhoto(file, { ...meta, uploadedBy: currentUser }); setPhotos(current => [photo, ...current]); return photo }) }; const onPhotoUpdate = (id, patch) => { if (!cloudEnabled) { setPhotos(current => current.map(photo => { if (patch.isDayCover && photo.day === current.find(item => item.id === id)?.day) return { ...photo, isDayCover: photo.id === id }; if (patch.isTripCover) return { ...photo, isTripCover: photo.id === id }; return photo.id === id ? { ...photo, ...patch } : photo })); return }; sync(() => updatePhoto(id, patch)) }; const onPhotoDelete = photo => { if (!cloudEnabled) { setPhotos(current => { const remaining = current.filter(item => item.id !== photo.id); const fallback = remaining.find(item => item.day === photo.day); return remaining.map(item => fallback && !remaining.some(candidate => candidate.day === photo.day && candidate.isDayCover) && item.id === fallback.id ? { ...item, isDayCover: true } : item) }); return }; sync(() => deletePhoto(photo)) };
  const safeDecisions = decisions && typeof decisions === 'object' ? decisions : {}; const matchCount = places.filter(place => place.votes?.Jenny === 'want' && place.votes?.Richard === 'want').length + Object.values(safeDecisions).filter(item => item?.jenny && item?.richard).length; const doneCount = Object.values(completed || {}).filter(Boolean).length; const isMemory = selectedId === 'memory'; const stage = dayMap[selectedId] || dayMap.pre
  return <div className="app-shell"><SyncBanner status={status} /><header className="topbar"><a className="brand" href="#top"><span className="brand-dot" /> Anji / Trip OS</a><button className="menu-toggle" type="button" onClick={() => setNavOpen(value => !value)}>{navOpen ? '×' : 'Menu'}</button><nav className={navOpen ? 'nav-links is-open' : 'nav-links'}><a href="#today" onClick={() => setNavOpen(false)}>Today</a><a href="#decisions" onClick={() => setNavOpen(false)}>Decide</a><a href="#vault" onClick={() => setNavOpen(false)}>Photos</a><a href="#memory" onClick={() => setNavOpen(false)}>Memory</a></nav></header><main id="top" className={isMemory ? 'memory-active' : ''}><section className="hero"><img src={heroImage} alt="安吉山野旅行明信片插画" className="hero-image" fetchPriority="high" /><div className="hero-overlay" /><div className="hero-content"><div className="hero-sticker">JULY 28—31 · SHANGHAI → ANJI</div><p className="hero-kicker">A little invitation for two</p><h1>山里有风，<br />也有我们</h1><p className="hero-en-title">Into the Green, With You</p><div className="hero-meta"><span>安吉中南度假 · 东非草原酒店</span></div><div className="hero-bottom"><a className="scroll-cue" href="#today">今天开始<br /><span>↓</span></a></div></div></section>{isMemory ? <MemoryMode selectedId={selectedId} setSelectedId={setSelectedView} photos={photos} memories={memories} decisions={safeDecisions} completedTasks={completedTasks} seal={seal} setSeal={setSeal} /> : <TodayMode stage={stage} autoId={autoId} selectedId={selectedId} setSelectedId={setSelectedView} checklist={checklist} toggleChecklist={toggleChecklist} ready={ready} toggleReady={toggleReady} />}<PlanSection activeDay={isMemory ? 'day1' : selectedId === 'pre' ? 'day1' : selectedId} setActiveDay={setSelectedView} completed={completed} togglePlan={togglePlan} /><DecisionBoard places={places} currentUser={currentUser} onVote={onVote} onAdd={onPlaceAdd} onUpdate={onPlaceUpdate} onDelete={onPlaceDelete} cloudMode={cloudEnabled} /><ChecklistSection items={packingItems} currentUser={currentUser} onToggle={onPackingToggle} onAdd={onPackingAdd} onUpdate={onPackingUpdate} onDelete={onPackingDelete} cloudMode={cloudEnabled} /><CoupleMode taskIndex={taskIndex} setTaskIndex={setTaskIndex} questionIndex={questionIndex} setQuestionIndex={setQuestionIndex} taskDone={completedTasks} setTaskDone={setCompletedTasks} couple={couple} setCouple={setCouple} /><PhotoVault photos={photos} currentUser={currentUser} cloudMode={cloudEnabled} onUpload={onPhotoUpload} onUpdate={onPhotoUpdate} onDelete={onPhotoDelete} /><MemorySection memories={memories} setMemories={setMemories} /><section className="closing-section"><p className="eyebrow">A small proof</p><h2>{matchCount ? `${matchCount} 个 Match，` : '没有急着决定，'}<br /><em>也很好。</em></h2><p className="closing-copy">这里不是安排表，<br />是我们一起选过的证据。</p><div className="closing-mark">♡</div><p className="closing-note">有风、有水、还有两个人都点过的按钮。</p></section></main><footer className="footer"><span>Anji / Trip OS</span><span>{doneCount} plans checked · {matchCount} matches</span><a href="#today">回到 Today ↗</a></footer><BottomNav />{!currentUser && <IdentityModal onSelect={setCurrentUser} />}</div>
}

createRoot(document.getElementById('root')).render(<App />)
